struct FEMenuEntry { int entry_num; };

class PanelQuad {
public:
    void TurnOn(bool on);
    void GetFade(int& fade, float& alpha, float& timer);
    void SetFade(int fade, float alpha, float timer);
};

class FEGraphicalMenu {
protected:
    char state_before_highlighted[76];
    FEMenuEntry *highlighted;
    char state_after_highlighted[284];
public:
    virtual void OnUp(int c);
};

struct SoundScriptManager {
    static SoundScriptManager *inst() { return *(SoundScriptManager **)0x0046B4A0; }
    void playEvent(int event, void *entity = 0, float volume = 0.0f);
};

enum { SS_FE_UPDOWN = 25 };

class OptionsMenu : public FEGraphicalMenu
{
    enum { OpEnd = 11 };
    static const int MAX_VOLUME = 10;
    static const int NUM_VOLUME = 5;
    PanelQuad* levels[NUM_VOLUME][MAX_VOLUME];
    PanelQuad* lights[OpEnd];
public:
    virtual void OnUp(int c);
};

